"use client"

import * as React from "react"
import * as ProgressPrimitive from "@radix-ui/react-progress"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"
import { springStateChange } from "@/lib/motion"

const Progress = React.forwardRef<
  React.ElementRef<typeof ProgressPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof ProgressPrimitive.Root>
>(({ className, value, ...props }, ref) => (
  <ProgressPrimitive.Root
    ref={ref}
    className={cn(
      "relative h-4 w-full overflow-hidden rounded-full bg-secondary",
      className
    )}
    {...props}
  >
    <ProgressPrimitive.Indicator asChild>
      <motion.div
        className="h-full w-full flex-1 bg-primary"
        animate={{ x: `-${100 - (value || 0)}%` }}
        transition={springStateChange}
        initial={false}
      />
    </ProgressPrimitive.Indicator>
  </ProgressPrimitive.Root>
))
Progress.displayName = ProgressPrimitive.Root.displayName

export { Progress }

"use client"

import { useEffect, useState } from "react"
import type { RefObject } from "react"

export const springInteraction = {
  type: "spring" as const,
  stiffness: 500,
  damping: 35,
}

export const springStateChange = {
  type: "spring" as const,
  stiffness: 400,
  damping: 30,
}

export function useDataState(ref: RefObject<HTMLElement | null>): string | null {
  const [state, setState] = useState<string | null>(null)

  useEffect(() => {
    const el = ref.current
    if (!el) return

    setState(el.getAttribute("data-state"))

    const observer = new MutationObserver(() => {
      setState(el.getAttribute("data-state"))
    })

    observer.observe(el, { attributes: true, attributeFilter: ["data-state"] })

    return () => observer.disconnect()
  }, [ref])

  return state
}
